-- NEXA Gaming starter content for local development and new environments. -- Prices and promotions below are illustrative. Verify regional pricing, -- publisher terms, fulfillment, and artwork rights before accepting sales. -- This seed intentionally creates no auth users, admins, customers, orders, -- payment records, testimonials, or coupon codes.  -- Storefront settings. The site_settings table is created by the migrations. insert into public.site_settings (key, value) values (   'storefront',   jsonb_build_object(     'storeName', 'NEXA Gaming',     'description', 'Instant game credits, currency, and digital top-ups built for gamers.',     'supportEmail', 'support@example.com',     'heroBadge', 'THE NEXT LEVEL STARTS HERE',     'heroTitle', 'Power up',     'heroHighlight', 'your game.',     'heroDescription', 'Instant game credits, currency, and digital top-ups built for gamers who play to win.',     'heroImage', 'photo-1542751371-adc38448a05e'   ) ) on conflict (key) do update set value = excluded.value;  -- Categories used to group catalog cards. Game platforms are stored on games -- and also participate in the storefront's platform filters. insert into public.categories (name, slug, description, sort_order, is_active) values   ('Tactical FPS', 'tactical-fps', 'Competitive tactical shooters and their top-ups.', 10, true),   ('Battle Royale', 'battle-royale', 'Battle royale games and seasonal content.', 20, true),   ('Action RPG', 'action-rpg', 'Adventure and action role-playing games.', 30, true),   ('MOBA', 'moba', 'Multiplayer online battle arena games.', 40, true),   ('Sports', 'sports', 'Sports games and in-game points.', 50, true),   ('Gift Cards', 'gift-cards', 'Digital gift cards and redeemable game credit.', 60, true),   ('Shooter', 'shooter', 'First-person and action shooters.', 70, true),   ('Battle Pass', 'battle-pass', 'Season passes and progression packs.', 80, true),   ('PC', 'pc', 'Games and products available on PC.', 90, true),   ('Console', 'console', 'Games and products available on console.', 100, true),   ('Mobile', 'mobile', 'Games and products available on mobile.', 110, true) on conflict (slug) do update set   name = excluded.name,   description = excluded.description,   sort_order = excluded.sort_order,   is_active = excluded.is_active;  -- Catalog games. Category IDs are resolved by slug so the seed is repeatable -- and does not rely on generated UUIDs. insert into public.games   (name, slug, description, cover_url, platform, is_featured, category_id, sort_order, is_active) select   v.name, v.slug, v.description, v.cover_url, v.platform, v.is_featured,   c.id, v.sort_order, true from (values   ('VALORANT', 'valorant', 'VALORANT Points for your next match.', 'https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1200&q=85', 'PC', true, 'tactical-fps', 10),   ('Fortnite', 'fortnite', 'V-Bucks and seasonal content for Fortnite.', 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=1200&q=85', 'PC ┬╖ Console', true, 'battle-royale', 20),   ('PUBG MOBILE', 'pubg-mobile', 'Unknown Cash for PUBG MOBILE.', 'https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&w=1200&q=85', 'Mobile', true, 'battle-royale', 30),   ('Genshin Impact', 'genshin-impact', 'Genesis Crystals and Blessing of the Welkin Moon.', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1200&q=85', 'PC ┬╖ Console ┬╖ Mobile', true, 'action-rpg', 40),   ('Free Fire', 'free-fire', 'Diamonds for Free Fire and Free Fire MAX.', 'https://images.unsplash.com/photo-1493711662062-fa541adb3fc8?auto=format&fit=crop&w=1200&q=85', 'Mobile', true, 'battle-royale', 50),   ('League of Legends', 'league-of-legends', 'Riot Points for your favorite League content.', 'https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1200&q=85', 'PC', false, 'moba', 60),   ('Roblox', 'roblox', 'Roblox digital credit and gift cards.', 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=1200&q=85', 'PC ┬╖ Console ┬╖ Mobile', true, 'gift-cards', 70),   ('EA SPORTS FC', 'ea-sports-fc', 'FC Points for EA SPORTS FC.', 'https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1200&q=85', 'PC ┬╖ Console', false, 'sports', 80),   ('Call of Duty', 'call-of-duty', 'Call of Duty Points and digital content.', 'https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1200&q=85', 'PC ┬╖ Console', false, 'shooter', 90),   ('Apex Legends', 'apex-legends', 'Apex Coins for Legends and cosmetics.', 'https://images.unsplash.com/photo-1493711662062-fa541adb3fc8?auto=format&fit=crop&w=1200&q=85', 'PC ┬╖ Console', false, 'battle-royale', 100) ) as v(name, slug, description, cover_url, platform, is_featured, category_slug, sort_order) join public.categories c on c.slug = v.category_slug on conflict (slug) do update set   name = excluded.name,   description = excluded.description,   cover_url = excluded.cover_url,   platform = excluded.platform,   is_featured = excluded.is_featured,   category_id = excluded.category_id,   sort_order = excluded.sort_order,   is_active = excluded.is_active;  -- Each product row is a purchasable pack (the application does not use a -- separate product_variants table). Amounts/prices are sample catalog values. insert into public.products   (game_id, category_id, name, slug, description, currency_amount, price,    compare_at_price, image_url, region, platform, is_active) select   g.id, c.id, v.name, v.slug, v.description, v.amount, v.price,   v.compare_at_price, g.cover_url, v.region, g.platform, true from (values   ('valorant', 'tactical-fps', 'VALORANT Points', 'valorant-475-vp', '475 VALORANT Points digital top-up.', '475 VP', 4.99::numeric, null::numeric, 'Global'),   ('valorant', 'tactical-fps', 'VALORANT Points', 'valorant-1000-vp', '1,000 VALORANT Points digital top-up.', '1,000 VP', 9.99::numeric, 11.99::numeric, 'Global'),   ('valorant', 'tactical-fps', 'VALORANT Points', 'valorant-2050-vp', '2,050 VALORANT Points digital top-up.', '2,050 VP', 19.99::numeric, null::numeric, 'Global'),   ('fortnite', 'battle-royale', 'Fortnite V-Bucks', 'fortnite-1000-v-bucks', '1,000 V-Bucks digital top-up.', '1,000 V-Bucks', 8.99::numeric, null::numeric, 'Global'),   ('fortnite', 'battle-royale', 'Fortnite V-Bucks', 'fortnite-2800-v-bucks', '2,800 V-Bucks digital top-up.', '2,800 V-Bucks', 22.99::numeric, 25.99::numeric, 'Global'),   ('fortnite', 'battle-pass', 'Fortnite Battle Pass', 'fortnite-battle-pass', 'Current Fortnite Battle Pass.', 'Battle Pass', 9.99::numeric, null::numeric, 'Global'),   ('pubg-mobile', 'battle-royale', 'PUBG MOBILE UC', 'pubg-mobile-60-uc', '60 Unknown Cash for PUBG MOBILE.', '60 UC', 0.99::numeric, null::numeric, 'Global'),   ('pubg-mobile', 'battle-royale', 'PUBG MOBILE UC', 'pubg-mobile-325-uc', '325 Unknown Cash for PUBG MOBILE.', '325 UC', 4.99::numeric, null::numeric, 'Global'),   ('pubg-mobile', 'battle-royale', 'PUBG MOBILE UC', 'pubg-mobile-660-uc', '660 Unknown Cash for PUBG MOBILE.', '660 UC', 9.99::numeric, 11.99::numeric, 'Global'),   ('genshin-impact', 'action-rpg', 'Blessing of the Welkin Moon', 'genshin-welkin-moon', 'Blessing of the Welkin Moon for Genshin Impact.', 'Welkin Moon', 4.99::numeric, null::numeric, 'Global'),   ('genshin-impact', 'action-rpg', 'Genesis Crystals', 'genshin-300-genesis-crystals', 'Genesis Crystals digital top-up.', '300 + 30 Crystals', 4.99::numeric, null::numeric, 'Global'),   ('genshin-impact', 'action-rpg', 'Genesis Crystals', 'genshin-980-genesis-crystals', 'Genesis Crystals digital top-up.', '980 + 110 Crystals', 14.99::numeric, 19.99::numeric, 'Global'),   ('free-fire', 'battle-royale', 'Free Fire Diamonds', 'free-fire-100-diamonds', '100 diamonds for Free Fire.', '100 Diamonds', 0.99::numeric, null::numeric, 'Global'),   ('free-fire', 'battle-royale', 'Free Fire Diamonds', 'free-fire-520-diamonds', '520 diamonds for Free Fire.', '520 Diamonds', 4.99::numeric, null::numeric, 'Global'),   ('free-fire', 'battle-royale', 'Free Fire Diamonds', 'free-fire-1080-diamonds', '1,080 diamonds for Free Fire.', '1,080 Diamonds', 9.99::numeric, 11.99::numeric, 'Global'),   ('league-of-legends', 'moba', 'Riot Points', 'league-575-rp', '575 Riot Points for League of Legends.', '575 RP', 4.99::numeric, null::numeric, 'Global'),   ('league-of-legends', 'moba', 'Riot Points', 'league-1380-rp', '1,380 Riot Points for League of Legends.', '1,380 RP', 9.99::numeric, 11.99::numeric, 'Global'),   ('league-of-legends', 'moba', 'Riot Points', 'league-2800-rp', '2,800 Riot Points for League of Legends.', '2,800 RP', 19.99::numeric, null::numeric, 'Global'),   ('roblox', 'gift-cards', 'Roblox Digital Gift Card', 'roblox-800-robux', 'Roblox digital credit. Availability may vary by region.', '800 Robux', 9.99::numeric, null::numeric, 'Global'),   ('roblox', 'gift-cards', 'Roblox Digital Gift Card', 'roblox-1700-robux', 'Roblox digital credit. Availability may vary by region.', '1,700 Robux', 19.99::numeric, 22.99::numeric, 'Global'),   ('ea-sports-fc', 'sports', 'EA SPORTS FC Points', 'ea-fc-1050-points', '1,050 FC Points digital top-up.', '1,050 FC Points', 9.99::numeric, null::numeric, 'Global'),   ('ea-sports-fc', 'sports', 'EA SPORTS FC Points', 'ea-fc-2800-points', '2,800 FC Points digital top-up.', '2,800 FC Points', 24.99::numeric, 29.99::numeric, 'Global'),   ('call-of-duty', 'shooter', 'Call of Duty Points', 'call-of-duty-500-cp', '500 Call of Duty Points digital top-up.', '500 CP', 4.99::numeric, null::numeric, 'Global'),   ('call-of-duty', 'shooter', 'Call of Duty Points', 'call-of-duty-1100-cp', '1,100 Call of Duty Points digital top-up.', '1,100 CP', 9.99::numeric, 11.99::numeric, 'Global'),   ('apex-legends', 'battle-royale', 'Apex Coins', 'apex-1000-coins', '1,000 Apex Coins digital top-up.', '1,000 Coins', 9.99::numeric, null::numeric, 'Global'),   ('apex-legends', 'battle-royale', 'Apex Coins', 'apex-2150-coins', '2,150 Apex Coins digital top-up.', '2,150 Coins', 19.99::numeric, 24.99::numeric, 'Global') ) as v(game_slug, category_slug, name, slug, description, amount, price, compare_at_price, region) join public.games g on g.slug = v.game_slug join public.categories c on c.slug = v.category_slug on conflict (slug) do update set   game_id = excluded.game_id,   category_id = excluded.category_id,   name = excluded.name,   description = excluded.description,   currency_amount = excluded.currency_amount,   price = excluded.price,   compare_at_price = excluded.compare_at_price,   image_url = excluded.image_url,   region = excluded.region,   platform = excluded.platform,   is_active = excluded.is_active;  -- One live, one scheduled, and one expired example demonstrate derived offer -- status. Existence checks make repeat runs avoid duplicate offers. with offer_seed(title, description, discount_type, discount_value, game_slug, starts_at, ends_at, sort_order) as (   values     ('VALORANT Launch Drop', 'A sample limited-time discount on VALORANT Points.', 'percentage', 10::numeric, 'valorant', now() - interval '1 day', now() + interval '6 days', 10),     ('Battle Royale Weekend Drop', 'A sample scheduled discount for Fortnite.', 'percentage', 10::numeric, 'fortnite', now() + interval '7 days', now() + interval '10 days', 20),     ('Genshin Welcome Drop', 'An expired example retained for admin schedule history.', 'fixed', 1::numeric, 'genshin-impact', now() - interval '10 days', now() - interval '3 days', 30) ) insert into public.offers   (title, description, discount_type, discount_value, game_id, starts_at, ends_at, sort_order, is_active) select s.title, s.description, s.discount_type, s.discount_value, g.id, s.starts_at, s.ends_at, s.sort_order, true from offer_seed s join public.games g on g.slug = s.game_slug where not exists (   select 1 from public.offers existing   where existing.title = s.title and existing.game_id = g.id );